'use client';

import { useState } from 'react';
import { banUser, unbanUser, verifyUser } from '@/actions/user-mutations';
import { resolveDispute } from '@/actions/dispute-mutations';
import { createTestDispute } from '@/actions/test-helpers';
import { useRouter } from 'next/navigation';

export function TestControls({ users, disputes, adminId }: { users: any[], disputes: any[], adminId: string }) {
  const router = useRouter();
  const [loading, setLoading] = useState<string | null>(null);
  const [result, setResult] = useState<string>('');

  const handleBan = async (userId: string) => {
    setLoading(userId);
    try {
      await banUser(adminId, userId, 'Violation of terms (Test)');
      setResult(`Banned user ${userId}`);
      router.refresh();
    } catch (e: any) {
      setResult(`Error: ${e.message}`);
    }
    setLoading(null);
  };

  const handleUnban = async (userId: string) => {
    setLoading(userId);
    try {
      await unbanUser(adminId, userId);
      setResult(`Unbanned user ${userId}`);
      router.refresh();
    } catch (e: any) {
      setResult(`Error: ${e.message}`);
    }
    setLoading(null);
  };

  const handleVerify = async (userId: string) => {
    setLoading(userId);
    try {
      await verifyUser(adminId, userId);
      setResult(`Verified user ${userId}`);
      router.refresh();
    } catch (e: any) {
      setResult(`Error: ${e.message}`);
    }
    setLoading(null);
  };

  const handleCreateDispute = async () => {
    setLoading('create_dispute');
    try {
      const dispute = await createTestDispute(adminId);
      setResult(`Created dispute ${dispute.id}`);
      router.refresh();
    } catch (e: any) {
      setResult(`Error: ${e.message}`);
    }
    setLoading(null);
  };

  const handleResolve = async (disputeId: string, decision: 'refund_client' | 'release_freelancer') => {
    setLoading(disputeId);
    try {
      await resolveDispute(adminId, disputeId, decision);
      setResult(`Resolved dispute ${disputeId} with ${decision}`);
      router.refresh();
    } catch (e: any) {
      setResult(`Error: ${e.message}`);
    }
    setLoading(null);
  };

  return (
    <div className="space-y-8">
      {result && <div className="p-4 bg-yellow-100 mb-4 rounded">{result}</div>}
      
      <section>
        <h3 className="text-lg font-bold mb-2">Users</h3>
        <div className="grid gap-2">
            {users.map(u => (
                <div key={u.id} className="p-2 border rounded flex justify-between items-center">
                    <div>
                        <span className="font-bold">{u.full_name}</span> ({u.email})
                        <div className="text-xs text-gray-500">
                             Status: {u.status} | Verified: {u.metadata?.is_verified ? 'YES' : 'NO'} | Roles: {u.roles?.join(', ')}
                        </div>
                    </div>
                    <div className="space-x-2">
                        <button 
                            onClick={() => handleBan(u.id)} 
                            disabled={loading === u.id}
                            className="bg-red-500 text-white px-2 py-1 rounded text-xs">
                            Ban
                        </button>
                        <button 
                            onClick={() => handleUnban(u.id)} 
                            disabled={loading === u.id}
                            className="bg-green-500 text-white px-2 py-1 rounded text-xs">
                            Unban
                        </button>
                        <button 
                            onClick={() => handleVerify(u.id)} 
                            disabled={loading === u.id}
                            className="bg-blue-500 text-white px-2 py-1 rounded text-xs">
                            Verify
                        </button>
                    </div>
                </div>
            ))}
        </div>
      </section>

      <section>
        <h3 className="text-lg font-bold mb-2">Disputes</h3>
        <button onClick={handleCreateDispute} disabled={loading === 'create_dispute'} className="mb-2 bg-gray-800 text-white px-3 py-1 rounded text-sm">
            + Create Test Dispute
        </button>
        <div className="grid gap-2">
            {disputes.map(d => (
                <div key={d.id} className="p-2 border rounded flex justify-between items-center">
                    <div>
                        <span className="font-bold">ID: {d.id}</span>
                        <div className="text-xs text-gray-500">
                             Status: {d.status} | Task: {d.task_id}
                        </div>
                    </div>
                    {d.status === 'open' && (
                        <div className="space-x-2">
                            <button 
                                onClick={() => handleResolve(d.id, 'refund_client')} 
                                disabled={loading === d.id}
                                className="bg-orange-500 text-white px-2 py-1 rounded text-xs">
                                Refund Client
                            </button>
                            <button 
                                onClick={() => handleResolve(d.id, 'release_freelancer')} 
                                disabled={loading === d.id}
                                className="bg-purple-500 text-white px-2 py-1 rounded text-xs">
                                Release to Freelancer
                            </button>
                        </div>
                    )}
                </div>
            ))}
        </div>
      </section>
    </div>
  );
}
